\section{Introduction}

A \emph{magma} is a set with a binary operation and no axioms. The collection of
all magma structures on a fixed carrier set $X$ is enormous---$n^{n^2}$ of them
when $|X| = n$---and structureless until one notices, as Kim and Neggers did,
that it carries a natural monoid product. Given two operations $f$ and $g$,
define
\[
  (f*g)(a,b) = g\bigl(f(a,b), f(b,a)\bigr).
\]
To evaluate the product at $(a,b)$ one applies $f$ in both argument orders and
feeds the pair of results to $g$. The resulting structure
$\Bin(X) = (X^{X\times X}, *)$ is the \emph{magma monoid}.

Two facts are immediate. \emph{Associativity}: for all $f,g,h$ and all $a,b$,
\[
  ((f*g)*h)(a,b) = h\bigl(g(f(a,b),f(b,a)),\, g(f(b,a),f(a,b))\bigr) = (f*(g*h))(a,b).
\]
\emph{Identity}: the \emph{left projection} $\ell(a,b) = a$ satisfies
$\ell * g = g$ and $f*\ell = f$. Moreover the \emph{right projection}
$r(a,b) = b$ satisfies $r*g = g*r$ for all $g$ and $r*r = \ell$.

Our aim is to determine the structure of $\Bin(X)$ completely, using one
organizing principle: $\Bin(X)$ \emph{is} a transformation monoid, namely the
monoid of self-maps of $X \times X$ commuting with reversal. Every structural
question then becomes a question about images, kernels and the diagonal, and
the diagonal is where all the interesting obstructions live.

\subsection*{Notation}
$X$ is an arbitrary set; $\mathcal{O}(X) = X^{X\times X}$ is the set of binary
operations and $\Bin(X)$ the same set with the product $*$;
$\sigma(a,b) = (b,a)$ is \emph{reversal}; $\Delta = \{(x,x)\} \subseteq X\times X$
is the \emph{diagonal}, the fixed-point set of $\sigma$; $T(Y)$ is the monoid of
all self-maps of $Y$; $\widehat f(a,b) = (f(a,b), f(b,a))$ is the
\emph{unfolding} of $f$; $\Ima(f) = \widehat f(X\times X)$ is the \emph{pair
image}; $\Diag(f) = \{(f(z,z), f(z,z)) : z \in X\}$ the \emph{diagonal image};
and $\Com(f) = \Ima(f) \cap \Delta$ the \emph{commutative image}. Always
$\Diag(f) \subseteq \Com(f)$; the reverse inclusion is the crux of the theory.

\section{The representation theorem}

\begin{definition}
A map $T : X\times X \to X \times X$ is a \emph{pairmorph} (or
\emph{reversal-equivariant}) if $T\circ\sigma = \sigma\circ T$.
\end{definition}

\begin{lemma}\label{lem:unfold}
For every $f \in \mathcal{O}(X)$ the unfolding $\widehat f$ is a pairmorph, and
$\widehat{f*g} = \widehat g \circ \widehat f$.
\end{lemma}

\begin{proof}
$\widehat f(\sigma(a,b)) = (f(b,a), f(a,b)) = \sigma(\widehat f(a,b))$. For the
product, $\widehat{f*g}(a,b) = \bigl(g(f(a,b),f(b,a)), g(f(b,a),f(a,b))\bigr)
= \widehat g(\widehat f(a,b))$.
\end{proof}

\begin{lemma}\label{lem:faithful}
The assignment $f \mapsto \widehat f$ is injective with image exactly the set of
pairmorphs: if $T$ is a pairmorph then $T = \widehat f$ for
$f(a,b) = \pi_1(T(a,b))$.
\end{lemma}

\begin{proof}
Injectivity: $f(a,b) = \pi_1(\widehat f(a,b))$. Surjectivity: with $f$ as
stated, $\widehat f(a,b) = (\pi_1 T(a,b), \pi_1 T(b,a))$, and
$T(b,a) = \sigma(T(a,b))$ shows the second coordinate is $\pi_2(T(a,b))$.
\end{proof}

Write $C_{T(X\times X)}(\sigma)$ for the centralizer of $\sigma$ in
$T(X\times X)$; by Lemma~\ref{lem:unfold} it is exactly the submonoid of
pairmorphs.

\begin{theorem}[Representation theorem]\label{thm:rep}
Unfolding is an anti-isomorphism of monoids
\[
  \Bin(X) \;\xrightarrow{\ \sim\ }\; C_{T(X\times X)}(\sigma)^{\op},
  \qquad f \longmapsto \widehat f .
\]
\end{theorem}

\begin{corollary}[Units]\label{cor:units}
$f$ is invertible in $\Bin(X)$ if and only if $\widehat f$ is a bijection of
$X\times X$.
\end{corollary}

\begin{proof}
If $g$ inverts $f$ then $\widehat g\widehat f = \widehat f\widehat g = \mathrm{id}$.
Conversely, if $\widehat f$ is bijective its set-theoretic inverse $T$ is again
a pairmorph (apply the injective $\widehat f$ to both sides of
$T\sigma = \sigma T$), so $T = \widehat g$ and $g$ inverts $f$.
\end{proof}

\begin{corollary}
$|\Bin(X)| = n^{n^2}$ for $|X| = n$.
\end{corollary}

\section{Regularity: the diagonal obstruction}

\begin{definition}
An element $f$ of a semigroup is \emph{(von Neumann) regular} if $f*g*f = f$ for
some $g$, called a \emph{pseudo-inverse}.
\end{definition}

Every element of $T(Y)$ is regular: choose a preimage for each image point. In
the pairmorph submonoid the section must itself be equivariant, and a pairmorph
maps $\Delta$ into $\Delta$; a diagonal image point must therefore be reached
from a diagonal point. This is the entire obstruction, as the following
selection lemma shows.

\begin{lemma}[Equivariant selection]\label{lem:selection}
Let $F,G$ be pairmorphs of $X\times X$ and $S \subseteq X\times X$ be
$\sigma$-invariant. Assume (i) for every $p \in S$ there is $r$ with
$F(r) = G(p)$, and (ii) for every $a$ with $(a,a) \in S$ there is $z \in X$ with
$F(z,z) = G(a,a)$. Then there is a pairmorph $U$ with $F(U(p)) = G(p)$ for all
$p \in S$.
\end{lemma}

\begin{proof}[Proof sketch]
Well-order $X$. The $\sigma$-orbits on $X\times X$ are the singletons
$\{(a,a)\}$ and the pairs $\{(a,b),(b,a)\}$ with $a \ne b$. Define $U$ orbit by
orbit: on a diagonal point use the $z$ from (ii); on a two-element orbit choose
the representative $(a,b)$ with $a<b$, set $U(a,b) = r$ from (i), and
$U(b,a) = \sigma(r)$. Equivariance is immediate, and correctness at $(b,a)$
follows from $F(\sigma r) = \sigma F(r) = \sigma G(a,b) = G(b,a)$. Hypothesis
(ii) is exactly what makes the diagonal case consistent, since equivariance
forces $U(a,a)$ to be $\sigma$-fixed.
\end{proof}

\begin{theorem}[Regularity criterion]\label{thm:reg}
For $f \in \mathcal{O}(X)$ the following are equivalent:
\begin{enumerate}
\item $f$ is regular in $\Bin(X)$;
\item $\Com(f) = \Diag(f)$;
\item for all $x,y \in X$: $f(x,y) = f(y,x)$ implies $f(z,z) = f(x,y)$ for some
$z \in X$.
\end{enumerate}
\end{theorem}

\begin{proof}
(1)$\Rightarrow$(2): if $\widehat f\widehat g\widehat f = \widehat f$ and
$q = \widehat f(p) \in \Delta$, then $\widehat g(q) \in \Delta$ since pairmorphs
preserve $\Delta$; writing $\widehat g(q) = (z,z)$ gives $\widehat f(z,z) = q$.
(2)$\Leftrightarrow$(3) is unwinding of definitions. (2)$\Rightarrow$(1): apply
Lemma~\ref{lem:selection} with $F = \widehat f$, $G = \mathrm{id}$ and
$S = \Ima(f)$, which is $\sigma$-invariant; hypothesis (i) holds by definition
of the image and (ii) is $\Com(f) \subseteq \Diag(f)$. The resulting pairmorph
$U$ satisfies $\widehat f U \widehat f = \widehat f$ and folds back
(Lemma~\ref{lem:faithful}) to a pseudo-inverse.
\end{proof}

Criterion (3) costs $O(n^2)$ table lookups for $|X| = n$, replacing an
existential quantifier over $n^{n^2}$ candidates.

\begin{corollary}\label{cor:regexamples}
The following are regular: every idempotent of $\Bin(X)$; every diagonally
idempotent operation ($f(z,z) = z$), in particular every semilattice operation,
$\min$ and $\max$; every operation with surjective diagonal map
$z \mapsto f(z,z)$.
\end{corollary}

\begin{theorem}[Non-regularity]\label{thm:nonreg}
If $|X| \ge 2$ then $\Bin(X)$ is not a regular monoid. For $a \ne b$ the
operation $d_{a,b}(x,y) = a$ if $x=y$ and $b$ otherwise is not regular:
$d_{a,b}(a,b) = d_{a,b}(b,a) = b$ is a commutative value, but the only diagonal
value is $a$.
\end{theorem}

The smallest instance: on $X = \{0,1\}$, $\mathrm{XOR}$ is commutative with
diagonal identically $0$, so the commutative value $1$ is unattainable.

\begin{proposition}[Census for $|X| = 2$]
Exactly $14$ of the $16$ binary operations on a two-element set are regular; the
exceptions are $\mathrm{XOR}$ and $\mathrm{XNOR}$. Exactly $7$ of the $16$ are
idempotent for $*$.
\end{proposition}

\begin{proposition}[Regular elements are not closed under $*$]
With tables written $\left(\begin{smallmatrix} f(0,0) & f(0,1)\\ f(1,0) &
f(1,1)\end{smallmatrix}\right)$, the operations
$f = \left(\begin{smallmatrix}0&0\\1&0\end{smallmatrix}\right)$ and
$g = \left(\begin{smallmatrix}0&1\\1&1\end{smallmatrix}\right)$ are regular,
while $f*g = \mathrm{XOR}$ is not. Hence the regular elements of $\Bin(X)$ do
not form a submonoid.
\end{proposition}

\begin{proposition}
$f$ is regular if and only if $f$ is $\mathcal{L}$-equivalent to an idempotent,
if and only if $f$ is $\mathcal{R}$-equivalent to an idempotent.
\end{proposition}

\begin{proof}
If $f*g*f = f$ then $e = f*g$ is idempotent and $\mathcal{R}$-equivalent to $f$,
while $e' = g*f$ is idempotent and $\mathcal{L}$-equivalent to $f$. Conversely
$\mathcal{R}$-equivalence to an idempotent $e$ gives $e*f = f$ and hence a
pseudo-inverse, and dually for $\mathcal{L}$.
\end{proof}

\section{Divisibility and Green's relations}

In $\Bin(X)$, left multiplication $u \mapsto u*f$ unfolds to precomposition of
$\widehat f$ (shrinking images) and right multiplication to postcomposition
(coarsening kernels): the classical dictionary, with the sides exchanged by the
anti-isomorphism of Theorem~\ref{thm:rep}.

\begin{theorem}[Left divisibility]\label{thm:leftdiv}
$\exists u:\ u*f = g$ if and only if $\Ima(g) \subseteq \Ima(f)$ and
$\Diag(g)\subseteq\Diag(f)$.
\end{theorem}

\begin{proof}
($\Rightarrow$) $\widehat g = \widehat f\circ\widehat u$ gives both inclusions.
($\Leftarrow$) Apply Lemma~\ref{lem:selection} with $F = \widehat f$,
$G = \widehat g$, $S = X\times X$: the two inclusions are exactly hypotheses (i)
and (ii).
\end{proof}

The second condition is invisible in $T(X\times X)$; it is the price of
equivariance.

\begin{theorem}[Green's $\mathcal{L}$]\label{thm:L}
$f \mathrel{\mathcal{L}} g$ if and only if $\Ima(f) = \Ima(g)$ and
$\Diag(f) = \Diag(g)$.
\end{theorem}

\begin{lemma}[Equivariant kernel transport]\label{lem:transport}
Let $F,H$ be pairmorphs with $\ker F \subseteq \ker H$. Then $U\circ F = H$ for
some pairmorph $U$.
\end{lemma}

\begin{proof}
Set $U(s) = H(p)$ for any $p$ with $F(p) = s$ (well defined by hypothesis), and
$U(s) = s$ off $\Ima(F)$. On the image, equivariance follows from
$\sigma F = F\sigma$ and $\sigma H = H\sigma$; off the image $U$ is the
identity, and the complement of $\Ima(F)$ is $\sigma$-invariant.
\end{proof}

\begin{theorem}[Right divisibility and Green's $\mathcal{R}$]\label{thm:R}
$\exists u:\ f*u = g$ if and only if $\ker\widehat f \subseteq \ker\widehat g$.
Consequently $f\mathrel{\mathcal{R}}g$ if and only if
$\ker\widehat f = \ker \widehat g$.
\end{theorem}

\begin{theorem}[Green's $\mathcal{H}$]
$f\mathrel{\mathcal{H}}g$ if and only if $\Ima(f) = \Ima(g)$,
$\Diag(f) = \Diag(g)$ and $\ker\widehat f = \ker\widehat g$.
\end{theorem}

\begin{theorem}[Green's $\mathcal{D}$]\label{thm:D}
$f \mathrel{\mathcal{D}} g$ if and only if there is a pairmorph $\beta$ of
$X\times X$, injective on $\Ima(g)$, with
$\beta(\Ima(g)) = \Ima(f)$ and $\beta(\Diag(g)) = \Diag(f)$.
\end{theorem}

\begin{proof}[Proof sketch]
($\Rightarrow$) If $f\mathrel{\mathcal{L}}h\mathrel{\mathcal{R}}g$ then
$\ker\widehat g = \ker\widehat h$, so Lemma~\ref{lem:transport} yields a
pairmorph $\beta$ with $\beta\circ\widehat g = \widehat h$; equality of kernels
makes $\beta$ injective on $\Ima(g)$, and Theorem~\ref{thm:L} transfers images
and diagonal images. ($\Leftarrow$) Let $h$ be the operation unfolding to
$\beta\circ\widehat g$. Then $h\mathrel{\mathcal{L}}f$ by Theorem~\ref{thm:L}
and $h \mathrel{\mathcal{R}} g$ by Theorem~\ref{thm:R}.
\end{proof}

\begin{theorem}[Regularity is a $\mathcal{D}$-invariant]\label{thm:Dinv}
If $f\mathrel{\mathcal{D}}g$ then $f$ is regular if and only if $g$ is.
\end{theorem}

\begin{proof}
Let $\beta$ be as in Theorem~\ref{thm:D} and assume $\Com(f) = \Diag(f)$. If
$q \in \Com(g)$ then $\sigma\beta(q) = \beta(\sigma q) = \beta(q)$, so
$\beta(q) \in \Com(f) = \Diag(f) = \beta(\Diag(g))$; injectivity of $\beta$ on
$\Ima(g)$ gives $q \in \Diag(g)$. Hence $\Com(g)\subseteq\Diag(g)$, and the
reverse inclusion is automatic.
\end{proof}

\begin{example}
For $|X| = 2$ exhaustive computation gives $8$ $\mathcal{L}$-classes (sizes
$4,4,2,2,1,1,1,1$), $6$ $\mathcal{R}$-classes (sizes $4,4,2,2,2,2$), $9$
$\mathcal{H}$-classes and $5$ $\mathcal{D}$-classes (sizes $4,4,4,2,2$). The
$\mathcal{D}$-class $\{\mathrm{XOR},\mathrm{XNOR}\}$ is precisely the set of
non-regular elements.
\end{example}

\section{The centre}

\begin{definition}
$f$ is \emph{central} if $f*g = g*f$ for all $g \in \mathcal{O}(X)$.
\end{definition}

Both projections are central: $\ell$ is the identity, while
$(r*g)(a,b) = g(b,a) = (g*r)(a,b)$ and $(r*r)(a,b) = a$, so $r*r=\ell$.

\begin{lemma}\label{lem:diagidem}
If $f$ is central then $f(c,c) = c$ for all $c$.
\end{lemma}

\begin{proof}
Test against the constant $k_c(a,b) = c$: $(f*k_c)(a,b) = c$ and
$(k_c*f)(a,b) = f(c,c)$.
\end{proof}

\begin{lemma}\label{lem:endo}
If $f$ is central then $h(f(a,b)) = f(h(a),h(b))$ for every self-map $h$ of $X$
and all $a,b$.
\end{lemma}

\begin{proof}
Test against $g_h(a,b) = h(a)$: $(f*g_h)(a,b) = h(f(a,b))$ and
$(g_h*f)(a,b) = f(h(a),h(b))$.
\end{proof}

Thus a central operation is one for which \emph{every} self-map of $X$ is an
endomorphism of the magma $(X,f)$.

\begin{lemma}\label{lem:pair}
If $f$ is central then $f(a,b) \in \{a,b\}$ for all $a,b$.
\end{lemma}

\begin{proof}
For $a \ne b$ let $h$ send $b \mapsto a$ and fix all other points. Then
Lemmas~\ref{lem:endo} and~\ref{lem:diagidem} give
$h(f(a,b)) = f(a,a) = a$, and $h^{-1}(a) = \{a,b\}$. The case $a = b$ is
Lemma~\ref{lem:diagidem}.
\end{proof}

\begin{theorem}[The centre of the magma monoid]
If $X$ has at least two elements then
$Z(\Bin(X)) = \{\ell, r\} \cong \Zm/2$, the group of order two generated by the
right projection.
\end{theorem}

\begin{proof}
Fix $a \ne b$. By Lemma~\ref{lem:pair}, $f(a,b) \in \{a,b\}$. Suppose
$f(a,b) = a$ and let $c,d \in X$. If $c = d$ then $f(c,d) = c$ by
Lemma~\ref{lem:diagidem}. Otherwise let $h$ send $a\mapsto c$ and all other
points to $d$; then $f(c,d) = f(h(a),h(b)) = h(f(a,b)) = c$. Hence $f = \ell$;
symmetrically $f(a,b) = b$ forces $f = r$. Finally $\ell \ne r$ and
$r * r = \ell$.
\end{proof}

\section{The unit group}

By Corollary~\ref{cor:units} and Theorem~\ref{thm:rep},
$\Bin(X)^{\times} \cong C_{\Sym(X\times X)}(\sigma)^{\op}$.

\begin{lemma}
For $|X| = n$, the permutation $\sigma$ of $X\times X$ is an involution with $n$
fixed points and $m = n(n-1)/2$ two-cycles; its cycle type is $2^m 1^n$.
\end{lemma}

\begin{theorem}[Order of the unit group]
For $|X| = n$,
\[
  \bigl|\Bin(X)^{\times}\bigr| = n!\cdot 2^{m}\cdot m!, \qquad m = \frac{n(n-1)}2 .
\]
\end{theorem}

\begin{proof}
The centralizer of a permutation with $c_k$ cycles of length $k$ has order
$\prod_k k^{c_k}c_k!$; here $c_1 = n$ and $c_2 = m$.
\end{proof}

Structurally this is the shadow of a direct product: a reversal-commuting
permutation permutes the diagonal arbitrarily and permutes the $m$ mirror pairs
with independent flips, i.e.\ lies in
$\Sym(n)\times(\Zm/2 \wr \Sym(m))$.

