\section{The general equivariant theorem}

Let a group $G$ act on a set $Y$ and let $\End_G(Y)$ be the monoid of
$G$-equivariant self-maps of $Y$. Write $G_y$ for the stabilizer of $y$.

\begin{theorem}[Stabilizer-controlled equivariant section]\label{thm:section}
Let $T \in \End_G(Y)$ and suppose every $y \in \Ima(T)$ has a preimage $z$ with
$G_y \subseteq G_z$. Then there is $U \in \End_G(Y)$ with $T(U(y)) = y$ for all
$y \in \Ima(T)$.
\end{theorem}

\begin{proof}[Proof sketch]
The image of an equivariant map is $G$-invariant. Choose a representative
$\rho(y)$ in each orbit, so $\rho(g\cdot y) = \rho(y)$ and
$\rho(y) = g_y^{-1}\cdot y$ for a chosen $g_y \in G$. For each representative
$p \in \Ima(T)$ pick $z_p$ with $T(z_p) = p$ and $G_p \subseteq G_{z_p}$, and set
$U(y) = g_y\cdot z_{\rho(y)}$ when $\rho(y) \in \Ima(T)$, and $U(y) = y$
otherwise. Correctness is $T(U(y)) = g_y\cdot\rho(y) = y$. For equivariance,
$g_{h\cdot y}$ and $hg_y$ both carry $\rho(y)$ to $h\cdot y$, so
$(hg_y)^{-1}g_{h\cdot y}$ stabilizes $\rho(y)$ and hence, by hypothesis, also
$z_{\rho(y)}$; therefore $g_{h\cdot y}\cdot z_{\rho(y)} = h\cdot (g_y\cdot
z_{\rho(y)})$. The stabilizer hypothesis is precisely the well-definedness
condition for equivariant transport.
\end{proof}

\begin{theorem}[Regularity in an equivariant transformation monoid]\label{thm:eqreg}
For $T \in \End_G(Y)$ the following are equivalent:
\begin{enumerate}
\item there is $U \in \End_G(Y)$ with $TUT = T$;
\item every $y \in \Ima(T)$ has a preimage $z$ with $G_y \subseteq G_z$.
\end{enumerate}
\end{theorem}

\begin{proof}
(2)$\Rightarrow$(1) is Theorem~\ref{thm:section}. (1)$\Rightarrow$(2): for
$y = T(x)$ take $z = U(T(x))$; if $g\cdot y = y$ then
$g\cdot z = U(g\cdot y) = z$.
\end{proof}

\begin{corollary}
For the trivial group this says $T(Y)$ is a regular monoid. If $G$ acts freely
on $\Ima(T)$, then $T$ is regular in $\End_G(Y)$: all obstruction to regularity
is concentrated at points with non-trivial stabilizer.
\end{corollary}

\begin{remark}
Taking $G = \Zm/2$ acting on $Y = X\times X$ by reversal, equivariance is the
pairmorph condition and the points with non-trivial stabilizer are exactly the
diagonal points; Theorem~\ref{thm:eqreg} becomes Theorem~\ref{thm:reg}.
\end{remark}

\section{Tropical operations inside the magma monoid}

\subsection{Tropical addition: a left-zero band}

\begin{proposition}\label{prop:leftzero}
If $f$ is commutative and $g$ is diagonally idempotent then $f*g = f$.
\end{proposition}

\begin{proof}
$(f*g)(a,b) = g(f(a,b), f(b,a)) = g(f(a,b),f(a,b)) = f(a,b)$.
\end{proof}

\begin{corollary}
The set $B(X)$ of commutative, diagonally idempotent operations---all
semilattice operations, in particular $\min$ and $\max$---is a \emph{left-zero
band}: $f*g = f$ for all $f,g \in B(X)$. Every element of $B(X)$ is idempotent
and regular, all have $\Ima(f) = \Diag(f) = \Delta$, and any two of them are
$\mathcal{L}$-equivalent.
\end{corollary}

\begin{theorem}[The tropical band]
For linearly ordered $X$, the submonoid of $\Bin(X)$ generated by $\min$ and
$\max$ is $\{\ell, \min, \max\}$, with
$\min*\min = \min*\max = \min$ and $\max*\min = \max*\max = \max$: every
non-empty word collapses to its first letter.
\end{theorem}

\subsection{Tropical multiplication: regularity detects 2-divisibility}

Let $R$ be a commutative additive monoid and consider tropical multiplication
$\mu(a,b) = a+b$ as an element of $\Bin(R)$. It is commutative, and its diagonal
values are $\mu(z,z) = 2z$.

\begin{theorem}\label{thm:trop}
$\mu$ is regular in $\Bin(R)$ if and only if $R$ is $2$-divisible: every
$r \in R$ is of the form $s+s$.
\end{theorem}

\begin{proof}
By Theorem~\ref{thm:reg}(3), regularity says that for all $a,b$ there is $z$
with $2z = a+b$. Taking $b = 0$ gives $2$-divisibility; conversely
$2$-divisibility applied to $r = a+b$ supplies $z$.
\end{proof}

\begin{corollary}
Tropical multiplication is regular over $\Qm$ and over $\Rm$, and not regular
over $\Zm$: the value $1$ is a commutative value never attained on the diagonal,
since $1$ is odd.
\end{corollary}

A purely semigroup-theoretic invariant of the monoid of all binary operations
thus detects an arithmetic property of the coefficient semiring.

\section{Algorithms}

For $|X| = n$ with operations given as $n\times n$ tables:

\begin{enumerate}
\item \emph{Regularity test.} Compute $D = \{f(z,z)\}$ in $O(n)$; for each pair
$(x,y)$ with $f(x,y) = f(y,x)$ check $f(x,y) \in D$. Total $O(n^2)$, versus
$n^{n^2}$ for naive search.
\item \emph{Green tests.} Compute $\Ima(f)$, $\Diag(f)$ and the kernel partition
of $X\times X$ induced by $\widehat f$, each in $O(n^2)$, and compare.
\item \emph{Pseudo-inverse construction.} Fix a total order on $X$; for a
diagonal image point $(u,u)$ set $U(u,u) = (z,z)$ with $f(z,z) = u$; for an
off-diagonal image point $(u,v)$ with $u<v$ pick any preimage $(x,y)$ and set
$U(u,v) = (x,y)$, $U(v,u) = (y,x)$; extend by the identity and return
$g(a,b) = \pi_1(U(a,b))$. Cost $O(n^2)$.
\item \emph{Unit test.} $f$ is a unit iff $\widehat f$ is injective, testable in
$O(n^2)$; units are enumerable as (permutation of the diagonal, signed
permutation of the mirror pairs).
\end{enumerate}

\section{Discussion}

Passing from $T(X\times X)$ to the reversal-equivariant submonoid changes the
theory in exactly one place: statements about \emph{images} acquire a diagonal
decoration, statements about \emph{kernels} do not. The asymmetry is structural:
factoring \emph{through} a map can be repaired off the image by the identity,
which is automatically equivariant, while factoring \emph{into} a map cannot,
because the fixed-point set must map to the fixed-point set. This is why
$\mathcal{R}$ is classical, $\mathcal{L}$ is not, and the monoid fails to be
regular. Theorem~\ref{thm:eqreg} identifies the general mechanism: obstructions
to regularity in an equivariant transformation monoid live exactly at points
with non-trivial stabilizer. Finally, Theorem~\ref{thm:trop} shows that these
semigroup-theoretic invariants can encode arithmetic: the classification of a
single operation inside $\Bin(R)$ detects $2$-divisibility of $R$.

\begin{remark}[A numerical observation]
Uniform random sampling of tables ($20\,000$ samples per $n$) suggests that the
proportion of regular operations \emph{decreases} with $n$: approximately
$0.875$ (exactly $14/16$) at $n = 2$, $0.74$ at $n=3$, $0.62$ at $n=4$, $0.53$
at $n=5$ and $0.16$ at $n=12$. The heuristic is that a random table offers only
$n$ diagonal values while generating a growing number of accidental
coincidences $f(x,y) = f(y,x)$ to be covered; the asymptotics are open. This is
a sampling estimate, not a theorem.
\end{remark}

\section{Future directions}

\begin{conjecture}[Structure of the unit group]
For $|X| = n$ and $m = n(n-1)/2$,
$\Bin(X)^{\times}\cong \bigl(\Sym(n)\times(\Zm/2\wr\Sym(m))\bigr)^{\op}$,
the isomorphism induced by restricting a reversal-equivariant permutation of
$X\times X$ to the diagonal and to the set of reversal-orbits of off-diagonal
pairs. The order formula $n!\,2^m m!$ is precisely the shadow of this splitting.
\end{conjecture}

\begin{conjecture}[Classification of $\mathcal{L}$-classes]
For $|X| = n$ the $\mathcal{L}$-classes of $\Bin(X)$ are in bijection with pairs
$(P,D)$ where $P \subseteq X\times X$ is reversal-invariant and non-empty,
$D\subseteq P\cap\Delta$ with $|D| \le n$, and
$|(P\cap\Delta)\setminus D| + k(P) \le n(n-1)/2$, where $k(P)$ is the number of
two-element reversal-orbits contained in $P$. The $\mathcal{L}$-criterion
reduces an $\mathcal{L}$-class to the pair (pair image, diagonal image), so
classification becomes the combinatorial question of which such pairs are
realizable by an equivariant surjection $X\times X \twoheadrightarrow P$ sending
the diagonal onto $D$.
\end{conjecture}

\begin{conjecture}[$\mathcal{D} = \mathcal{J}$ and the ideal lattice]
For finite $X$ the relations $\mathcal{D}$ and $\mathcal{J}$ coincide on
$\Bin(X)$, and the principal-ideal order is induced by the pair (rank of the
image, rank of the diagonal image), so that the poset of $\mathcal{J}$-classes
is a two-dimensional grid truncated by realizability constraints.
\end{conjecture}

Further directions: extend the theory to $n$-ary operations with $\Sym(n)$
acting on argument tuples, where the diagonal is replaced by the stratification
of $X^n$ by partition type and one obstruction is predicted per stratum;
determine which classical magmas (groups, quasigroups, semilattices, racks) are
regular and describe their $\mathcal{D}$-classes; study the
idempotent-generated submonoid of $\Bin(X)$; and investigate which
semigroup-theoretic properties of $\Bin(R)$ correspond to divisibility
properties of the value monoid $R$.

\end{document}

