"""Diagonal-obstruction test for von Neumann regularity in the magma monoid."""

from __future__ import annotations

from typing import List, Optional, Sequence, Set, Tuple

Table = Sequence[int]  # flattened n x n table: f(a, b) = table[a * n + b]


def evaluate(table: Table, n: int, a: int, b: int) -> int:
    """f(a, b)."""
    return table[a * n + b]


def diagonal_values(table: Table, n: int) -> Set[int]:
    """{ f(z, z) : z in X } -- the values reachable from the diagonal."""
    return {evaluate(table, n, z, z) for z in range(n)}


def commutative_values(table: Table, n: int) -> Set[int]:
    """{ f(x, y) : f(x, y) = f(y, x) } -- the values whose image point is
    fixed by reversal."""
    return {evaluate(table, n, a, b)
            for a in range(n) for b in range(n)
            if evaluate(table, n, a, b) == evaluate(table, n, b, a)}


def regularity_obstruction(table: Table, n: int) -> Optional[Tuple[int, int, int]]:
    """
    Return None if the operation is regular, otherwise a witness (x, y, v) with
    f(x, y) = f(y, x) = v and v not of the form f(z, z).
    """
    diag = diagonal_values(table, n)
    for a in range(n):
        for b in range(n):
            v = evaluate(table, n, a, b)
            if v == evaluate(table, n, b, a) and v not in diag:
                return (a, b, v)
    return None


def is_regular(table: Table, n: int) -> bool:
    """f * g * f = f is solvable  <=>  no diagonal obstruction."""
    return regularity_obstruction(table, n) is None


def report(table: Table, n: int) -> str:
    w = regularity_obstruction(table, n)
    if w is None:
        return "regular: every commutative value is attained on the diagonal"
    a, b, v = w
    return (f"not regular: f({a},{b}) = f({b},{a}) = {v}, "
            f"but {v} is not among the diagonal values "
            f"{sorted(diagonal_values(table, n))}")


if __name__ == "__main__":
    XOR: List[int] = [0, 1, 1, 0]
    MIN3: List[int] = [min(a, b) for a in range(3) for b in range(3)]
    print("XOR on {0,1}   :", report(XOR, 2))
    print("min on {0,1,2} :", report(MIN3, 3))

