"""Green-class invariants: image, diagonal image, kernel, and the D-partition."""

from __future__ import annotations

from typing import Dict, FrozenSet, List, Sequence, Set, Tuple

Table = Sequence[int]
Pair = Tuple[int, int]


def evaluate(table: Table, n: int, a: int, b: int) -> int:
    return table[a * n + b]


def pair_image(table: Table, n: int) -> FrozenSet[Pair]:
    """Im(f) = fhat(X x X), a reversal-invariant subset of X x X."""
    return frozenset((evaluate(table, n, a, b), evaluate(table, n, b, a))
                     for a in range(n) for b in range(n))


def diagonal_image(table: Table, n: int) -> FrozenSet[Pair]:
    """Diag(f) = {(f(z,z), f(z,z))} -- the extra invariant forced by symmetry."""
    return frozenset((evaluate(table, n, z, z), evaluate(table, n, z, z))
                     for z in range(n))


def kernel(table: Table, n: int) -> FrozenSet[FrozenSet[Pair]]:
    """The partition of X x X into fibres of fhat."""
    blocks: Dict[Pair, Set[Pair]] = {}
    for a in range(n):
        for b in range(n):
            q = (evaluate(table, n, a, b), evaluate(table, n, b, a))
            blocks.setdefault(q, set()).add((a, b))
    return frozenset(frozenset(v) for v in blocks.values())


def L_invariant(table: Table, n: int) -> Tuple[FrozenSet[Pair], FrozenSet[Pair]]:
    """Complete invariant of the L-class: (pair image, diagonal image)."""
    return (pair_image(table, n), diagonal_image(table, n))


def R_invariant(table: Table, n: int) -> FrozenSet[FrozenSet[Pair]]:
    """Complete invariant of the R-class: the kernel."""
    return kernel(table, n)


def green_partition(tables: List[Table], n: int) -> List[List[int]]:
    """
    D = L o R, computed as the connected components of the graph on the given
    operations in which two operations are joined when they share an L- or an
    R-invariant.
    """
    parent = list(range(len(tables)))

    def find(x: int) -> int:
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(x: int, y: int) -> None:
        rx, ry = find(x), find(y)
        if rx != ry:
            parent[rx] = ry

    byL: Dict[object, int] = {}
    byR: Dict[object, int] = {}
    for i, t in enumerate(tables):
        kL, kR = L_invariant(t, n), R_invariant(t, n)
        if kL in byL:
            union(i, byL[kL])
        else:
            byL[kL] = i
        if kR in byR:
            union(i, byR[kR])
        else:
            byR[kR] = i

    comps: Dict[int, List[int]] = {}
    for i in range(len(tables)):
        comps.setdefault(find(i), []).append(i)
    return list(comps.values())


if __name__ == "__main__":
    from itertools import product
    n = 2
    tables = [list(t) for t in product(range(n), repeat=n * n)]
    comps = green_partition(tables, n)
    print(f"{len(tables)} operations on a {n}-element set")
    print("D-classes:", len(comps), "sizes:", sorted(len(c) for c in comps))
    Ls = {L_invariant(t, n) for t in tables}
    Rs = {R_invariant(t, n) for t in tables}
    print("L-classes:", len(Ls), "  R-classes:", len(Rs))
